def is_happy(s: str) -> bool:
    """
    Return True if the string is "happy", i.e. its length is at least 3 and
    every group of three consecutive characters are all distinct.
    """
    if len(s) < 3:
        return False
    for i in range(len(s) - 2):
        if len(set(s[i:i+3])) != 3:
            return False
    return True
