def largest_smallest_integers(lst):
    """
    Return a tuple (a, b) where:
    - a is the largest negative integer in lst (closest to zero),
    - b is the smallest positive integer in lst.
    If no negative or positive integers are present, the corresponding
    value is None.
    """
    max_neg = None
    min_pos = None

    for x in lst:
        if isinstance(x, int):
            if x < 0:
                if max_neg is None or x > max_neg:
                    max_neg = x
            elif x > 0:
                if min_pos is None or x < min_pos:
                    min_pos = x

    return (max_neg, min_pos)
